import Foundation
import NIO
import NIOWebSocket
import NIOHTTP1
import CryptoKit

struct EncryptedStore {
    private let key: SymmetricKey
    private var storage: [String: Data] = [:]

    init() {
        self.key = SymmetricKey(size: .bits256)
    }

    mutating func store(id: String, plaintext: String) throws {
        let nonce = AES.GCM.Nonce()
        let data = plaintext.data(using: .utf8)!
        let sealed = try AES.GCM.seal(data, using: key, nonce: nonce)
        storage[id] = sealed.combined!
    }

    func retrieve(id: String) throws -> String? {
        guard let combined = storage[id] else { return nil }
        let box = try AES.GCM.SealedBox(combined: combined)
        let decrypted = try AES.GCM.open(box, using: key)
        return String(data: decrypted, encoding: .utf8)
    }
}

class WebSocketHandler: ChannelInboundHandler {
    typealias InboundIn = WebSocketFrame
    typealias OutboundOut = WebSocketFrame

    private var store = EncryptedStore()
    private let allowedSchemes = Set(["https", "wss"])
    private let internalNetworks: [String] = ["10.", "172.16.", "192.168.", "127."]

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let frame = unwrapInboundIn(data)
        guard case .text = frame.opcode else { return }

        var buffer = frame.data
        guard let text = buffer.readString(length: buffer.readableBytes) else { return }

        handleMessage(context: context, message: text)
    }

    private func handleMessage(context: ChannelHandlerContext, message: String) {
        let parts = message.components(separatedBy: "|")
        guard parts.count >= 2 else { return }

        let command = parts[0]

        switch command {
        case "STORE":
            guard parts.count == 3 else { return }
            try? store.store(id: parts[1], plaintext: parts[2])
            sendResponse(context: context, text: "OK")

        case "RETRIEVE":
            if let value = try? store.retrieve(id: parts[1]) {
                sendResponse(context: context, text: value)
            }

        case "FETCH":
            guard parts.count == 2 else { return }
            let target = parts[1]
            fetchRemoteResource(context: context, urlString: target)

        case "FETCH_STORED":
            guard parts.count == 2 else { return }
            if let storedUrl = try? store.retrieve(id: parts[1]) {
                fetchRemoteResource(context: context, urlString: storedUrl)
            }

        default:
            sendResponse(context: context, text: "UNKNOWN_COMMAND")
        }
    }

    private func fetchRemoteResource(context: ChannelHandlerContext, urlString: String) {
        guard let url = URL(string: urlString) else {
            sendResponse(context: context, text: "INVALID_URL")
            return
        }

        guard let scheme = url.scheme?.lowercased(), allowedSchemes.contains(scheme) else {
            sendResponse(context: context, text: "BLOCKED_SCHEME")
            return
        }

        guard let host = url.host else {
            sendResponse(context: context, text: "NO_HOST")
            return
        }

        // Validate the host is not an internal network address
        guard !isInternalAddress(host: host) else {
            sendResponse(context: context, text: "BLOCKED_INTERNAL")
            return
        }

        // Resolve DNS and check the resolved IP
        let resolvedIP = resolveDNS(hostname: host)
        guard !isInternalAddress(host: resolvedIP) else {
            sendResponse(context: context, text: "BLOCKED_INTERNAL_RESOLVED")
            return
        }

        // Perform the actual fetch using the original URL
        performFetch(context: context, url: url)
    }

    private func isInternalAddress(host: String) -> Bool {
        for prefix in internalNetworks {
            if host.hasPrefix(prefix) { return true }
        }
        if host == "localhost" || host == "0.0.0.0" { return true }
        // Check for IPv6 loopback
        if host == "::1" || host == "[::1]" { return true }
        return false
    }

    private func resolveDNS(hostname: String) -> String {
        var hints = addrinfo()
        hints.ai_family = AF_INET
        hints.ai_socktype = SOCK_STREAM
        var result: UnsafeMutablePointer<addrinfo>?

        let status = getaddrinfo(hostname, nil, &hints, &result)
        defer { if result != nil { freeaddrinfo(result) } }

        guard status == 0, let addr = result else { return hostname }

        let sockAddr = addr.pointee.ai_addr!.withMemoryRebound(to: sockaddr_in.self, capacity: 1) { $0 }
        var ipBuffer = [CChar](repeating: 0, count: Int(INET_ADDRSTRLEN))
        var inAddr = sockAddr.pointee.sin_addr
        inet_ntop(AF_INET, &inAddr, &ipBuffer, socklen_t(INET_ADDRSTRLEN))

        return String(cString: ipBuffer)
    }

    private func performFetch(context: ChannelHandlerContext, url: URL) {
        let session = URLSession(configuration: .ephemeral)
        let task = session.dataTask(with: url) { [weak self] data, response, error in
            if let data = data, let body = String(data: data, encoding: .utf8) {
                self?.sendResponse(context: context, text: "FETCHED:\(body.prefix(1024))")
            } else {
                self?.sendResponse(context: context, text: "FETCH_ERROR")
            }
        }
        task.resume()
    }

    private func sendResponse(context: ChannelHandlerContext, text: String) {
        var buffer = context.channel.allocator.buffer(capacity: text.utf8.count)
        buffer.writeString(text)
        let frame = WebSocketFrame(fin: true, opcode: .text, data: buffer)
        context.writeAndFlush(wrapOutboundOut(frame), promise: nil)
    }
}

// Server bootstrap
let group = MultiThreadedEventLoopGroup(numberOfThreads: System.coreCount)
let bootstrap = ServerBootstrap(group: group)
    .childChannelInitializer { channel in
        let upgrader = NIOWebSocketServerUpgrader(
            shouldUpgrade: { head in HTTPHeaders() },
            upgradePipelineHandler: { channel, _ in
                channel.pipeline.addHandler(WebSocketHandler())
            }
        )
        return channel.pipeline.configureHTTPServerPipeline(withServerUpgrade: (upgraders: [upgrader], completionHandler: { _ in }))
    }

try bootstrap.bind(host: "0.0.0.0", port: 8080).wait()
